import torch
import torch.nn as nn
from cutegen.ptx_runtime import PtxModule, i32, u32, i64, u64, f32, f64
PTX_SOURCE = r"""
.version 8.0
.target sm_89
.address_size 64
.visible .entry layernorm_affine(
    .param .u64 p_in,
    .param .u64 p_out,
    .param .u64 p_gamma,
    .param .u64 p_beta,
    .param .u32 p_norm,
    .param .u32 p_batch,
    .param .f32 p_eps
)
{
    .reg .pred   %p<6>;
    .reg .b32    %r<30>;
    .reg .b64    %rd<60>;
    .reg .f32    %f<50>;
    .shared .align 16 .f32 sh_sum[1024];
    .shared .align 16 .f32 sh_sumsq[1024];
    .shared .align 4  .f32 sh_mean;
    .shared .align 4  .f32 sh_invstd;
    // Load params
    ld.param.u64    %rd10, [p_in];
    ld.param.u64    %rd11, [p_out];
    ld.param.u64    %rd12, [p_gamma];
    ld.param.u64    %rd13, [p_beta];
    ld.param.u32    %r20,  [p_norm];
    ld.param.u32    %r21,  [p_batch];
    ld.param.f32    %f20,  [p_eps];
    // Thread/block info
    mov.u32         %r0, %tid.x;
    mov.u32         %r1, %ntid.x;
    mov.u32         %r2, %ctaid.x;
    // Compute base element index for this sample: base = blockIdx.x * norm_size
    mul.wide.u32    %rd20, %r2, %r20;      // u64 elements
    mul.wide.u32    %rd21, %r20, 4;        // bytes per sample
    mul.wide.u32    %rd22, %r2, %r20;      // elements again
    mul.lo.u64      %rd23, %rd22, 4;       // bytes per sample
    mul.wide.u32    %rd24, %r0, 4;         // tid * 4 (bytes) for shared addressing convenience
    // Base pointers for this sample in/out
    mul.wide.u32    %rd25, %r2, %r20;      // elements
    mul.lo.u64      %rd26, %rd25, 4;       // bytes
    add.s64         %rd30, %rd10, %rd26;   // base_in = in + bytes
    add.s64         %rd31, %rd11, %rd26;   // base_out = out + bytes
    // Prepare shared memory base addresses
    mov.u64         %rd32, sh_sum;
    mov.u64         %rd33, sh_sumsq;
    mov.u64         %rd34, sh_mean;
    mov.u64         %rd35, sh_invstd;
    // ------------------------------------------------------------
    // Pass 1: compute partial sums over this sample (sum only)
    // ------------------------------------------------------------
    mov.f32         %f0, 0f00000000;       // sum = 0.0
    mov.f32         %f1, 0f00000000;       // (unused here, but keep for symmetry)
    mov.u32         %r3, %r0;              // idx = tid
L_loop_sum:
    // Vectorized pass: process 4 elements per iteration
    shr.u32         %r5, %r20, 2;              // N4 = N / 4
    mov.u32         %r3, %r0;                  // vec_idx = tid
L_loop_sum_vec:
    setp.ge.u32     %p0, %r3, %r5;
    @%p0 bra        L_done_sum_vec;
    mul.wide.u32    %rd1, %r3, 16;             // byte offset = vec_idx * 16
    add.s64         %rd2, %rd30, %rd1;         // addr = base_in + off
    ld.global.v4.f32 {%f2,%f3,%f4,%f5}, [%rd2];
    add.f32         %f0, %f0, %f2;
    add.f32         %f0, %f0, %f3;
    add.f32         %f0, %f0, %f4;
    add.f32         %f0, %f0, %f5;
    add.u32         %r3, %r3, %r1;             // vec_idx += blockDim.x
    bra             L_loop_sum_vec;
L_done_sum_vec:
    // Scalar tail for remaining N % 4 elements
    shl.b32         %r6, %r5, 2;               // base_scalar = N4 * 4
    add.u32         %r3, %r0, %r6;             // idx = tid + base_scalar
L_loop_sum_tail:
    setp.ge.u32     %p0, %r3, %r20;
    @%p0 bra        L_done_sum_tail;
    mul.wide.u32    %rd1, %r3, 4;
    add.s64         %rd2, %rd30, %rd1;
    ld.global.f32   %f2, [%rd2];
    add.f32         %f0, %f0, %f2;
    add.u32         %r3, %r3, %r1;
    bra             L_loop_sum_tail;
L_done_sum_tail:
    // Write partials to shared memory
    add.s64         %rd4, %rd32, %rd24;    // &sh_sum[tid]
    st.shared.f32   [%rd4], %f0;
    add.s64         %rd5, %rd33, %rd24;    // &sh_sumsq[tid] (will be ignored in pass 1 reduction)
    st.shared.f32   [%rd5], %f1;
    bar.sync 0;
    // Tree reduction in shared memory (reduce both buffers, but only sh_sum is used after this)
    // stride = 512
    setp.lt.u32 %p1, %r0, 512;
    @!%p1 bra   L_skip512;
        ld.shared.f32   %f4, [%rd4];
        add.s64         %rd6, %rd32, 2048;
        add.s64         %rd7, %rd6, %rd24;
        ld.shared.f32   %f5, [%rd7];
        add.f32         %f4, %f4, %f5;
        st.shared.f32   [%rd4], %f4;
        ld.shared.f32   %f6, [%rd5];
        add.s64         %rd8, %rd33, 2048;
        add.s64         %rd9, %rd8, %rd24;
        ld.shared.f32   %f7, [%rd9];
        add.f32         %f6, %f6, %f7;
        st.shared.f32   [%rd5], %f6;
L_skip512:
    bar.sync 0;
    // stride = 256
    setp.lt.u32 %p1, %r0, 256;
    @!%p1 bra   L_skip256;
        ld.shared.f32   %f4, [%rd4];
        add.s64         %rd6, %rd32, 1024;
        add.s64         %rd7, %rd6, %rd24;
        ld.shared.f32   %f5, [%rd7];
        add.f32         %f4, %f4, %f5;
        st.shared.f32   [%rd4], %f4;
        ld.shared.f32   %f6, [%rd5];
        add.s64         %rd8, %rd33, 1024;
        add.s64         %rd9, %rd8, %rd24;
        ld.shared.f32   %f7, [%rd9];
        add.f32         %f6, %f6, %f7;
        st.shared.f32   [%rd5], %f6;
L_skip256:
    bar.sync 0;
    // stride = 128
    setp.lt.u32 %p1, %r0, 128;
    @!%p1 bra   L_skip128;
        ld.shared.f32   %f4, [%rd4];
        add.s64         %rd6, %rd32, 512;
        add.s64         %rd7, %rd6, %rd24;
        ld.shared.f32   %f5, [%rd7];
        add.f32         %f4, %f4, %f5;
        st.shared.f32   [%rd4], %f4;
        ld.shared.f32   %f6, [%rd5];
        add.s64         %rd8, %rd33, 512;
        add.s64         %rd9, %rd8, %rd24;
        ld.shared.f32   %f7, [%rd9];
        add.f32         %f6, %f6, %f7;
        st.shared.f32   [%rd5], %f6;
L_skip128:
    bar.sync 0;
    // stride = 64
    setp.lt.u32 %p1, %r0, 64;
    @!%p1 bra   L_skip64;
        ld.shared.f32   %f4, [%rd4];
        add.s64         %rd6, %rd32, 256;
        add.s64         %rd7, %rd6, %rd24;
        ld.shared.f32   %f5, [%rd7];
        add.f32         %f4, %f4, %f5;
        st.shared.f32   [%rd4], %f4;
        ld.shared.f32   %f6, [%rd5];
        add.s64         %rd8, %rd33, 256;
        add.s64         %rd9, %rd8, %rd24;
        ld.shared.f32   %f7, [%rd9];
        add.f32         %f6, %f6, %f7;
        st.shared.f32   [%rd5], %f6;
L_skip64:
    bar.sync 0;
    // stride = 32
    setp.lt.u32 %p1, %r0, 32;
    @!%p1 bra   L_skip32;
        ld.shared.f32   %f4, [%rd4];
        add.s64         %rd6, %rd32, 128;
        add.s64         %rd7, %rd6, %rd24;
        ld.shared.f32   %f5, [%rd7];
        add.f32         %f4, %f4, %f5;
        st.shared.f32   [%rd4], %f4;
        ld.shared.f32   %f6, [%rd5];
        add.s64         %rd8, %rd33, 128;
        add.s64         %rd9, %rd8, %rd24;
        ld.shared.f32   %f7, [%rd9];
        add.f32         %f6, %f6, %f7;
        st.shared.f32   [%rd5], %f6;
L_skip32:
    bar.sync 0;
    // stride = 16
    setp.lt.u32 %p1, %r0, 16;
    @!%p1 bra   L_skip16;
        ld.shared.f32   %f4, [%rd4];
        add.s64         %rd6, %rd32, 64;
        add.s64         %rd7, %rd6, %rd24;
        ld.shared.f32   %f5, [%rd7];
        add.f32         %f4, %f4, %f5;
        st.shared.f32   [%rd4], %f4;
        ld.shared.f32   %f6, [%rd5];
        add.s64         %rd8, %rd33, 64;
        add.s64         %rd9, %rd8, %rd24;
        ld.shared.f32   %f7, [%rd9];
        add.f32         %f6, %f6, %f7;
        st.shared.f32   [%rd5], %f6;
L_skip16:
    bar.sync 0;
    // stride = 8
    setp.lt.u32 %p1, %r0, 8;
    @!%p1 bra   L_skip8;
        ld.shared.f32   %f4, [%rd4];
        add.s64         %rd6, %rd32, 32;
        add.s64         %rd7, %rd6, %rd24;
        ld.shared.f32   %f5, [%rd7];
        add.f32         %f4, %f4, %f5;
        st.shared.f32   [%rd4], %f4;
        ld.shared.f32   %f6, [%rd5];
        add.s64         %rd8, %rd33, 32;
        add.s64         %rd9, %rd8, %rd24;
        ld.shared.f32   %f7, [%rd9];
        add.f32         %f6, %f6, %f7;
        st.shared.f32   [%rd5], %f6;
L_skip8:
    bar.sync 0;
    // stride = 4
    setp.lt.u32 %p1, %r0, 4;
    @!%p1 bra   L_skip4;
        ld.shared.f32   %f4, [%rd4];
        add.s64         %rd6, %rd32, 16;
        add.s64         %rd7, %rd6, %rd24;
        ld.shared.f32   %f5, [%rd7];
        add.f32         %f4, %f4, %f5;
        st.shared.f32   [%rd4], %f4;
        ld.shared.f32   %f6, [%rd5];
        add.s64         %rd8, %rd33, 16;
        add.s64         %rd9, %rd8, %rd24;
        ld.shared.f32   %f7, [%rd9];
        add.f32         %f6, %f6, %f7;
        st.shared.f32   [%rd5], %f6;
L_skip4:
    bar.sync 0;
    // stride = 2
    setp.lt.u32 %p1, %r0, 2;
    @!%p1 bra   L_skip2;
        ld.shared.f32   %f4, [%rd4];
        add.s64         %rd6, %rd32, 8;
        add.s64         %rd7, %rd6, %rd24;
        ld.shared.f32   %f5, [%rd7];
        add.f32         %f4, %f4, %f5;
        st.shared.f32   [%rd4], %f4;
        ld.shared.f32   %f6, [%rd5];
        add.s64         %rd8, %rd33, 8;
        add.s64         %rd9, %rd8, %rd24;
        ld.shared.f32   %f7, [%rd9];
        add.f32         %f6, %f6, %f7;
        st.shared.f32   [%rd5], %f6;
L_skip2:
    bar.sync 0;
    // stride = 1
    setp.lt.u32 %p1, %r0, 1;
    @!%p1 bra   L_skip1;
        // sum: sh_sum[0] += sh_sum[1]
        ld.shared.f32   %f4, [%rd4];            // sh_sum[tid]
        add.s64         %rd6, %rd32, 4;         // base + 4 bytes
        add.s64         %rd7, %rd6, %rd24;      // sh_sum[tid + 1]
        ld.shared.f32   %f5, [%rd7];
        add.f32         %f4, %f4, %f5;
        st.shared.f32   [%rd4], %f4;
        // sumsq: sh_sumsq[0] += sh_sumsq[1]
        ld.shared.f32   %f6, [%rd5];            // sh_sumsq[tid]
        add.s64         %rd8, %rd33, 4;         // base + 4 bytes
        add.s64         %rd9, %rd8, %rd24;      // sh_sumsq[tid + 1]
        ld.shared.f32   %f7, [%rd9];
        add.f32         %f6, %f6, %f7;
        st.shared.f32   [%rd5], %f6;
L_skip1:
    bar.sync 0;
    // Compute mean by thread 0
    setp.eq.u32     %p2, %r0, 0;
    @!%p2 bra       L_after_mean;
        ld.shared.f32   %f8, [sh_sum];
        cvt.rn.f32.u32  %f10, %r20;            // N
        div.rn.f32      %f11, %f8, %f10;       // mean = sum / N
        st.shared.f32   [sh_mean], %f11;
L_after_mean:
    bar.sync 0;
    // ------------------------------------------------------------
    // Pass 2: accumulate sum of squared residuals (x - mean)^2
    // ------------------------------------------------------------
    ld.shared.f32   %f21, [sh_mean];
    mov.f32         %f1, 0f00000000;          // acc_sumsq = 0
    mov.u32         %r3, %r0;                 // idx = tid
L2_loop_sumsq:
    // Vectorized sumsq pass: 4 elements per iteration
    mov.u32         %r3, %r0;                 // vec_idx = tid
    shr.u32         %r5, %r20, 2;             // N4 = N / 4
L2_loop_sumsq_vec:
    setp.ge.u32     %p3, %r3, %r5;
    @%p3 bra        L2_done_sumsq_vec;
    mul.wide.u32    %rd40, %r3, 16;
    add.s64         %rd41, %rd30, %rd40;
    ld.global.v4.f32 {%f22,%f23,%f24,%f25}, [%rd41]; // x4
    sub.f32         %f26, %f22, %f21;
    sub.f32         %f27, %f23, %f21;
    sub.f32         %f28, %f24, %f21;
    sub.f32         %f29, %f25, %f21;
    mul.f32         %f26, %f26, %f26;
    mul.f32         %f27, %f27, %f27;
    mul.f32         %f28, %f28, %f28;
    mul.f32         %f29, %f29, %f29;
    add.f32         %f1, %f1, %f26;
    add.f32         %f1, %f1, %f27;
    add.f32         %f1, %f1, %f28;
    add.f32         %f1, %f1, %f29;
    add.u32         %r3, %r3, %r1;
    bra             L2_loop_sumsq_vec;
L2_done_sumsq_vec:
    // Scalar tail
    shl.b32         %r6, %r5, 2;               // base_scalar = N4*4
    add.u32         %r3, %r0, %r6;
L2_loop_sumsq_tail:
    setp.ge.u32     %p3, %r3, %r20;
    @%p3 bra        L2_done_sumsq_tail;
    mul.wide.u32    %rd40, %r3, 4;
    add.s64         %rd41, %rd30, %rd40;
    ld.global.f32   %f22, [%rd41];             // x
    sub.f32         %f23, %f22, %f21;          // dx
    mul.f32         %f24, %f23, %f23;          // dx^2
    add.f32         %f1, %f1, %f24;
    add.u32         %r3, %r3, %r1;
    bra             L2_loop_sumsq_tail;
L2_done_sumsq_tail:
    // Store partial sumsq; also zero sh_sum[tid] (not used further)
    add.s64         %rd4, %rd32, %rd24;       // &sh_sum[tid]
    mov.f32         %f25, 0f00000000;
    st.shared.f32   [%rd4], %f25;
    add.s64         %rd5, %rd33, %rd24;       // &sh_sumsq[tid]
    st.shared.f32   [%rd5], %f1;
    bar.sync 0;
    // Re-run the same tree reduction on sh_sumsq (sh_sum reduced but ignored)
    // stride = 512
    setp.lt.u32 %p1, %r0, 512;
    @!%p1 bra   L2_skip512;
        ld.shared.f32   %f4, [%rd4];
        add.s64         %rd6, %rd32, 2048;
        add.s64         %rd7, %rd6, %rd24;
        ld.shared.f32   %f5, [%rd7];
        add.f32         %f4, %f4, %f5;
        st.shared.f32   [%rd4], %f4;
        ld.shared.f32   %f6, [%rd5];
        add.s64         %rd8, %rd33, 2048;
        add.s64         %rd9, %rd8, %rd24;
        ld.shared.f32   %f7, [%rd9];
        add.f32         %f6, %f6, %f7;
        st.shared.f32   [%rd5], %f6;
L2_skip512:
    bar.sync 0;
    // stride = 256
    setp.lt.u32 %p1, %r0, 256;
    @!%p1 bra   L2_skip256;
        ld.shared.f32   %f4, [%rd4];
        add.s64         %rd6, %rd32, 1024;
        add.s64         %rd7, %rd6, %rd24;
        ld.shared.f32   %f5, [%rd7];
        add.f32         %f4, %f4, %f5;
        st.shared.f32   [%rd4], %f4;
        ld.shared.f32   %f6, [%rd5];
        add.s64         %rd8, %rd33, 1024;
        add.s64         %rd9, %rd8, %rd24;
        ld.shared.f32   %f7, [%rd9];
        add.f32         %f6, %f6, %f7;
        st.shared.f32   [%rd5], %f6;
L2_skip256:
    bar.sync 0;
    // stride = 128
    setp.lt.u32 %p1, %r0, 128;
    @!%p1 bra   L2_skip128;
        ld.shared.f32   %f4, [%rd4];
        add.s64         %rd6, %rd32, 512;
        add.s64         %rd7, %rd6, %rd24;
        ld.shared.f32   %f5, [%rd7];
        add.f32         %f4, %f4, %f5;
        st.shared.f32   [%rd4], %f4;
        ld.shared.f32   %f6, [%rd5];
        add.s64         %rd8, %rd33, 512;
        add.s64         %rd9, %rd8, %rd24;
        ld.shared.f32   %f7, [%rd9];
        add.f32         %f6, %f6, %f7;
        st.shared.f32   [%rd5], %f6;
L2_skip128:
    bar.sync 0;
    // stride = 64
    setp.lt.u32 %p1, %r0, 64;
    @!%p1 bra   L2_skip64;
        ld.shared.f32   %f4, [%rd4];
        add.s64         %rd6, %rd32, 256;
        add.s64         %rd7, %rd6, %rd24;
        ld.shared.f32   %f5, [%rd7];
        add.f32         %f4, %f4, %f5;
        st.shared.f32   [%rd4], %f4;
        ld.shared.f32   %f6, [%rd5];
        add.s64         %rd8, %rd33, 256;
        add.s64         %rd9, %rd8, %rd24;
        ld.shared.f32   %f7, [%rd9];
        add.f32         %f6, %f6, %f7;
        st.shared.f32   [%rd5], %f6;
L2_skip64:
    bar.sync 0;
    // stride = 32
    setp.lt.u32 %p1, %r0, 32;
    @!%p1 bra   L2_skip32;
        ld.shared.f32   %f4, [%rd4];
        add.s64         %rd6, %rd32, 128;
        add.s64         %rd7, %rd6, %rd24;
        ld.shared.f32   %f5, [%rd7];
        add.f32         %f4, %f4, %f5;
        st.shared.f32   [%rd4], %f4;
        ld.shared.f32   %f6, [%rd5];
        add.s64         %rd8, %rd33, 128;
        add.s64         %rd9, %rd8, %rd24;
        ld.shared.f32   %f7, [%rd9];
        add.f32         %f6, %f6, %f7;
        st.shared.f32   [%rd5], %f6;
L2_skip32:
    bar.sync 0;
    // stride = 16
    setp.lt.u32 %p1, %r0, 16;
    @!%p1 bra   L2_skip16;
        ld.shared.f32   %f4, [%rd4];
        add.s64         %rd6, %rd32, 64;
        add.s64         %rd7, %rd6, %rd24;
        ld.shared.f32   %f5, [%rd7];
        add.f32         %f4, %f4, %f5;
        st.shared.f32   [%rd4], %f4;
        ld.shared.f32   %f6, [%rd5];
        add.s64         %rd8, %rd33, 64;
        add.s64         %rd9, %rd8, %rd24;
        ld.shared.f32   %f7, [%rd9];
        add.f32         %f6, %f6, %f7;
        st.shared.f32   [%rd5], %f6;
L2_skip16:
    bar.sync 0;
    // stride = 8
    setp.lt.u32 %p1, %r0, 8;
    @!%p1 bra   L2_skip8;
        ld.shared.f32   %f4, [%rd4];
        add.s64         %rd6, %rd32, 32;
        add.s64         %rd7, %rd6, %rd24;
        ld.shared.f32   %f5, [%rd7];
        add.f32         %f4, %f4, %f5;
        st.shared.f32   [%rd4], %f4;
        ld.shared.f32   %f6, [%rd5];
        add.s64         %rd8, %rd33, 32;
        add.s64         %rd9, %rd8, %rd24;
        ld.shared.f32   %f7, [%rd9];
        add.f32         %f6, %f6, %f7;
        st.shared.f32   [%rd5], %f6;
L2_skip8:
    bar.sync 0;
    // stride = 4
    setp.lt.u32 %p1, %r0, 4;
    @!%p1 bra   L2_skip4;
        ld.shared.f32   %f4, [%rd4];
        add.s64         %rd6, %rd32, 16;
        add.s64         %rd7, %rd6, %rd24;
        ld.shared.f32   %f5, [%rd7];
        add.f32         %f4, %f4, %f5;
        st.shared.f32   [%rd4], %f4;
        ld.shared.f32   %f6, [%rd5];
        add.s64         %rd8, %rd33, 16;
        add.s64         %rd9, %rd8, %rd24;
        ld.shared.f32   %f7, [%rd9];
        add.f32         %f6, %f6, %f7;
        st.shared.f32   [%rd5], %f6;
L2_skip4:
    bar.sync 0;
